// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initVal, uint256 newVal, address actor) public {
        initVal = bound(initVal, 1, type(uint256).max / 2);
        newVal = bound(newVal, initVal + 1, type(uint256).max);
        if (actor == address(0)) actor = address(0xA11ce);

        vm.prank(actor);
        c.SetMinSum(initVal);
        c.Initialized();

        bool ok;
        vm.prank(actor);
        try c.SetMinSum(newVal) { ok = true; } catch { ok = false; }

        // After initialization, SetMinSum must revert and never change MinSum.
        assertTrue(!ok && c.MinSum() == initVal);
    }
}

