import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Recorder rec;

    function setUp() public {
        c = new C();
        rec = new Recorder();
        c.SetLogFile(address(rec));
        c.Initialized();
    }

    function testFuzz_property(address actor, uint256 amount, uint256 lockTime) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1e30);
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}(
            abi.encodeWithSignature("Put(uint256)", lockTime)
        );
        // General rule: a configured log must have recorded the put's sender.
